package io.github.testlens.migration.tooling;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.junit.jupiter.api.Assertions.*;

class MigrationRunOrchestrationTest {
    @TempDir Path temp;
    @Test void planIsDeterministicSecretFreeAndRequiresTwoTrustDimensions(){MigrationRunPlan a=plan("cp",MigrationRunPlan.SideEffectClassification.UNKNOWN,List.of("literal;$(touch nope)","`still-literal`"),List.of("PROVIDER_TOKEN"),List.of());MigrationRunPlan b=plan("cp",MigrationRunPlan.SideEffectClassification.UNKNOWN,List.of("literal;$(touch nope)","`still-literal`"),List.of("PROVIDER_TOKEN"),List.of());assertEquals(a.planId(),b.planId());assertEquals(List.of(MigrationAuthorization.Capability.EXECUTE_PROJECT_TEST_COMMAND,MigrationAuthorization.Capability.RUN_UNKNOWN_SIDE_EFFECT_TEST).stream().sorted().toList(),a.requiredApprovals());String json=new String(new MigrationArtifactJson().write(a),StandardCharsets.UTF_8);assertFalse(json.contains("actual-secret"));assertTrue(json.contains("PROVIDER_TOKEN"));}
    @Test void runnerSafeStopsWithoutApprovalAndKeepsMaliciousArgumentLiteral()throws Exception{Path java=java();MigrationRunPlan plan=plan("cp",MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("-cp",classPath(),Helper.class.getName(),"echo","; rm -rf /","$(ignored)","`ignored`"),List.of(),List.of());var local=new MigrationTrustedProcessRunner.LocalExecution("trusted-java",java,temp,binding(),null);var denied=new MigrationTrustedProcessRunner().run(plan,local,MigrationAuthorization.of("host"),MigrationTrustedProcessRunner.Cancellation.NEVER);assertEquals(MigrationTrustedProcessRunner.Raw.Status.SAFE_STOP,denied.status());var allowed=new MigrationTrustedProcessRunner().run(plan,local,MigrationAuthorization.of("host",MigrationAuthorization.Capability.EXECUTE_PROJECT_TEST_COMMAND,MigrationAuthorization.Capability.RUN_READ_ONLY_TEST),MigrationTrustedProcessRunner.Cancellation.NEVER);assertEquals(MigrationTrustedProcessRunner.Raw.Status.FINISHED,allowed.status());String output=new String(allowed.stdout(),StandardCharsets.UTF_8);assertTrue(output.contains("; rm -rf /|$(ignored)|`ignored`"));}
    @Test void runnerHandlesFailureOverflowTimeoutCancellationAndMissingExecutable()throws Exception{Path java=java();MigrationAuthorization approval=MigrationAuthorization.of("host",MigrationAuthorization.Capability.EXECUTE_PROJECT_TEST_COMMAND,MigrationAuthorization.Capability.RUN_UNKNOWN_SIDE_EFFECT_TEST);assertEquals(7,run(java,"fail",approval,Duration.ofSeconds(5),128,MigrationTrustedProcessRunner.Cancellation.NEVER).exitCode());var flood=run(java,"flood",approval,Duration.ofSeconds(5),128,MigrationTrustedProcessRunner.Cancellation.NEVER);assertTrue(flood.stdoutTruncated());assertTrue(flood.stderrTruncated());assertEquals(128,flood.stdout().length);var timeout=run(java,"sleep",approval,Duration.ofMillis(150),128,MigrationTrustedProcessRunner.Cancellation.NEVER);assertEquals(MigrationTrustedProcessRunner.Raw.Status.TIMED_OUT,timeout.status());assertNotEquals(MigrationRunResult.ProcessTreeTermination.DESCENDANTS_REMAIN,timeout.termination());AtomicBoolean cancel=new AtomicBoolean();Thread trigger=new Thread(()->{try{Thread.sleep(100);}catch(InterruptedException ignored){}cancel.set(true);});trigger.start();var cancelled=run(java,"child",approval,Duration.ofSeconds(10),128,cancel::get);trigger.join();assertEquals(MigrationTrustedProcessRunner.Raw.Status.CANCELLED,cancelled.status());assertNotEquals(MigrationRunResult.ProcessTreeTermination.DESCENDANTS_REMAIN,cancelled.termination());Path missing=temp.resolve("missing.exe");var local=new MigrationTrustedProcessRunner.LocalExecution("trusted-java",missing,temp,binding(),null);assertEquals(MigrationTrustedProcessRunner.Raw.Status.START_FAILED,new MigrationTrustedProcessRunner().run(plan("cp",MigrationRunPlan.SideEffectClassification.UNKNOWN,List.of(),List.of(),List.of()),local,approval,()->false).status());}
    @Test void orchestratorValidatesFreshArtifactAndDetectsStaleMalformedModeAndSourceMutation()throws Exception{Path repo=repo("runs");Files.writeString(repo.resolve(".gitignore"),"target/\n");Files.writeString(repo.resolve("source.txt"),"base");commit(repo);MigrationGitService git=new MigrationGitService();var inspected=git.inspect(repo);Path state=temp.resolve("state");Files.createDirectory(state);MigrationStateStore store=MigrationStateStore.resolve(git,inspected,state);MigrationCheckpoint cp=checkpoint(inspected,store);String worktree=inspected.preflight().worktreeBindingRef();MigrationAuthorization auth=MigrationAuthorization.of("host",MigrationAuthorization.Capability.EXECUTE_PROJECT_TEST_COMMAND,MigrationAuthorization.Capability.RUN_READ_ONLY_TEST);String manifest=manifest("HEADLESS","DEFAULT");MigrationStrictJson.object(manifest.getBytes(StandardCharsets.UTF_8));MigrationRunPlan.ExpectedArtifact artifact=new MigrationRunPlan.ExpectedArtifact("target/manifest.json",MigrationRunPlan.ArtifactRoot.PROJECT_OUTPUT,MigrationRunPlan.ArtifactFreshness.MUST_BE_CREATED,MigrationRunPlan.ArtifactKind.COMPATIBILITY_RUN_MANIFEST,1024*1024,null);MigrationRunPlan p=planAt(cp.checkpointId(),worktree,MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("-cp",classPath(),Helper.class.getName(),"write64","target/manifest.json",b64(manifest)),List.of(artifact));var local=new MigrationTrustedProcessRunner.LocalExecution("trusted-java",java(),repo,worktree,null);var ok=new MigrationRunOrchestrator().execute(p,cp,store,local,auth,()->false).durableResult();assertEquals(MigrationRunResult.Status.SUCCESS,ok.status(),ok.toString());assertEquals(MigrationRunResult.ArtifactStatus.VALID,ok.expectedArtifactResults().get(0).status());assertFalse(ok.issues().contains("SOURCE_STATE_CHANGED_BY_RUN"));MigrationRunPlan stale=planAt(ok.checkpointAfterRef(),worktree,MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("-cp",classPath(),Helper.class.getName(),"noop"),List.of(new MigrationRunPlan.ExpectedArtifact("target/manifest.json",MigrationRunPlan.ArtifactRoot.PROJECT_OUTPUT,MigrationRunPlan.ArtifactFreshness.MUST_CHANGE,MigrationRunPlan.ArtifactKind.COMPATIBILITY_RUN_MANIFEST,1024*1024,null)));MigrationCheckpoint after=store.read(findCheckpoint(state,ok.checkpointAfterRef()));assertEquals(MigrationRunResult.Status.ARTIFACT_VALIDATION_FAILED,new MigrationRunOrchestrator().execute(stale,after,store,local,auth,()->false).durableResult().status());Files.delete(repo.resolve("target/manifest.json"));MigrationRunPlan wrong=planAt(after.checkpointId(),worktree,MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("-cp",classPath(),Helper.class.getName(),"write64","target/manifest.json",b64(manifest("HEADED","DEFAULT"))),List.of(artifact));assertEquals(MigrationRunResult.ArtifactStatus.MODE_MISMATCH,new MigrationRunOrchestrator().execute(wrong,after,store,local,auth,()->false).durableResult().expectedArtifactResults().get(0).status());MigrationRunPlan mutate=planAt(after.checkpointId(),worktree,MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("-cp",classPath(),Helper.class.getName(),"write","source.txt","changed"),List.of());var changed=new MigrationRunOrchestrator().execute(mutate,after,store,local,auth,()->false).durableResult();assertTrue(changed.issues().contains("SOURCE_STATE_CHANGED_BY_RUN"));assertEquals(MigrationRunResult.Status.ARTIFACT_VALIDATION_FAILED,changed.status());}
    @Test void baselinesLedgerDryRunAndStrictCodecsRemainSeparated(){String cp=checkpointRef("cp"),source="migration-source-state-v1:sha256:"+"2".repeat(64),config="migration-configuration-v1:sha256:"+"3".repeat(64);MigrationBaseline original=MigrationBaseline.create(MigrationRunPlan.BaselineRole.ORIGINAL_BASELINE,cp,source,config,null,null,List.of(),List.of(),List.of(),MigrationBaseline.Completeness.NOT_RUN,List.of("COMMAND_NOT_SELECTED"));MigrationBaseline instrumented=MigrationBaseline.create(MigrationRunPlan.BaselineRole.INSTRUMENTED_BASELINE,cp,source,config,original.baselineId(),"instrumentation-delta-v1:sha256:"+"4".repeat(64),List.of(),List.of(),List.of(),MigrationBaseline.Completeness.EVIDENCE_SUPPLIED,List.of());assertNotEquals(original.baselineId(),instrumented.baselineId());MigrationRunPlan plan=plan("cp",MigrationRunPlan.SideEffectClassification.READ_ONLY,List.of("literal arg"),List.of("TOKEN_REF"),List.of());var dry=MigrationOrchestrationDryRunReport.create(null,List.of(plan),List.of(new MigrationOrchestrationDryRunReport.GitActionView(MigrationGitIsolationAction.Operation.CREATE_STASH,null,null,null,MigrationGitIsolationAction.StashScope.TRACKED_ONLY,List.of("CREATE_STASH"))),List.of("NO_SOURCE_APPLY"));String json=new String(new MigrationArtifactJson().write(dry),StandardCharsets.UTF_8);assertTrue(json.contains("TOKEN_REF"));assertFalse(json.contains("secret-value"));new MigrationArtifactJson().read(json.getBytes(StandardCharsets.UTF_8),MigrationArtifactJson.Kind.ORCHESTRATION_DRY_RUN);var entry=new MigrationRunLedger.Entry(plan.planId(),"migration-run-result-v1:sha256:"+"5".repeat(64),MigrationRunPlan.BaselineRole.ORIGINAL_BASELINE,cp,null,List.of(),MigrationRunResult.Status.INTERRUPTED,List.of());assertEquals(MigrationRunLedger.OrchestrationState.INTERRUPTED,MigrationRunLedger.create(List.of(entry),MigrationRunLedger.OrchestrationState.INTERRUPTED,List.of()).state());}
    private MigrationTrustedProcessRunner.Raw run(Path java,String mode,MigrationAuthorization approval,Duration timeout,int limit,MigrationTrustedProcessRunner.Cancellation cancellation){MigrationRunPlan p=MigrationRunPlan.create("trusted-java",List.of("-cp",classPath(),Helper.class.getName(),mode),binding(),Map.of(),List.of(),timeout,new MigrationRunPlan.OutputBounds(limit,limit),List.of(),MigrationRunPlan.ExecutionMode.CUSTOM_TRUSTED,MigrationRunPlan.Scope.SINGLE_TEST,MigrationRunPlan.SideEffectClassification.UNKNOWN,checkpointRef("cp"),MigrationRunPlan.BaselineRole.VARIANT);return new MigrationTrustedProcessRunner().run(p,new MigrationTrustedProcessRunner.LocalExecution("trusted-java",java,temp,binding(),null),approval,cancellation);}
    private MigrationRunPlan plan(String seed,MigrationRunPlan.SideEffectClassification side,List<String>args,List<String>secrets,List<MigrationRunPlan.ExpectedArtifact>artifacts){return MigrationRunPlan.create("trusted-java",args,binding(),Map.of(MigrationRunPlan.EnvironmentKey.CI,"true"),secrets,Duration.ofSeconds(10),MigrationRunPlan.OutputBounds.defaults(),artifacts,MigrationRunPlan.ExecutionMode.HEADLESS_STANDARD,MigrationRunPlan.Scope.SINGLE_TEST,side,checkpointRef(seed),MigrationRunPlan.BaselineRole.ORIGINAL_BASELINE);}
    private MigrationRunPlan planAt(String checkpoint,String worktree,MigrationRunPlan.SideEffectClassification side,List<String>args,List<MigrationRunPlan.ExpectedArtifact>artifacts){return MigrationRunPlan.create("trusted-java",args,worktree,Map.of(MigrationRunPlan.EnvironmentKey.CI,"true"),List.of(),Duration.ofSeconds(10),MigrationRunPlan.OutputBounds.defaults(),artifacts,MigrationRunPlan.ExecutionMode.HEADLESS_STANDARD,MigrationRunPlan.Scope.SINGLE_TEST,side,checkpoint,MigrationRunPlan.BaselineRole.ORIGINAL_BASELINE);}
    private static String binding(){return"migration-worktree-binding-v1:sha256:"+"1".repeat(64);}private static String checkpointRef(String seed){return"migration-checkpoint-v1:sha256:"+MigrationDigests.digest("test-checkpoint",seed);}private static Path java(){return Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name","").toLowerCase().contains("win")?"java.exe":"java").toAbsolutePath();}
    private static String classPath(){String separator=System.getProperty("path.separator");return java.util.Arrays.stream(System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(separator))).map(x->Path.of(x).toAbsolutePath().normalize().toString()).collect(java.util.stream.Collectors.joining(separator));}
    private Path repo(String name)throws Exception{Path p=temp.resolve(name);Files.createDirectory(p);git(p,"init");git(p,"config","user.email","test@example.invalid");git(p,"config","user.name","Test");return p;}private static void commit(Path p)throws Exception{git(p,"add","--all");git(p,"commit","-m","base");}private static void git(Path p,String...a)throws Exception{List<String>c=new java.util.ArrayList<>();c.add("git");c.addAll(List.of(a));Process x=new ProcessBuilder(c).directory(p.toFile()).redirectErrorStream(true).start();x.getInputStream().transferTo(java.io.OutputStream.nullOutputStream());assertEquals(0,x.waitFor());}
    private static MigrationCheckpoint checkpoint(MigrationGitService.Result r,MigrationStateStore store)throws Exception{MigrationCheckpoint cp=MigrationCheckpoint.create(r.preflight(),r.sourceState(),MigrationCheckpoint.Configuration.create(MigrationIsolationPlan.Choice.USE_CURRENT_WORKTREE,MigrationCheckpoint.IntendedMode.BASELINE_PREPARATION,store.storage()),List.of(),null,null);store.write(cp);return cp;}private static Path findCheckpoint(Path state,String id)throws Exception{return Files.walk(state).filter(p->p.getFileName().toString().equals(id.replace(':','-')+".json")).findFirst().orElseThrow();}
    private static String manifest(String headless,String observability){return"{\"schemaVersion\":1,\"manifestAlgorithmVersion\":1,\"manifestId\":\"compatibility-manifest-v1:sha256:"+"a".repeat(64)+"\",\"testIdentity\":{\"knowledge\":\"UNKNOWN\",\"provenance\":\"UNKNOWN\"},\"execution\":{\"effectiveHeadless\":{\"knowledge\":\"KNOWN\",\"provenance\":\"CAPABILITY_REPORTED\",\"value\":\""+headless+"\"},\"observabilityMode\":{\"knowledge\":\"KNOWN\",\"provenance\":\"TRUSTED_DESCRIPTOR\",\"value\":\""+observability+"\"}},\"browser\":{},\"display\":{},\"context\":{},\"configuration\":{},\"attempts\":[{}],\"terminalResult\":{},\"completeness\":{},\"issues\":[],\"evidenceDigests\":[]}";}private static String b64(String value){return java.util.Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8));}
    public static class Helper{public static void main(String[]a)throws Exception{switch(a[0]){case"echo"->System.out.print(String.join("|",java.util.Arrays.copyOfRange(a,1,a.length)));case"fail"->System.exit(7);case"sleep"->Thread.sleep(30_000);case"child"->{Process child=new ProcessBuilder(java().toString(),"-cp",classPath(),Helper.class.getName(),"sleep").start();child.waitFor();}case"flood"->{System.out.print("o".repeat(4096));System.err.print("e".repeat(4096));}case"write"->{Path p=Path.of(a[1]);if(p.getParent()!=null)Files.createDirectories(p.getParent());Files.writeString(p,a[2]);}case"write64"->{Path p=Path.of(a[1]);if(p.getParent()!=null)Files.createDirectories(p.getParent());Files.write(p,java.util.Base64.getDecoder().decode(a[2]));}case"noop"->{}}}}
}
